{"success": {"content": "{
  "mode": "server",
  "server": "assistant-ui",
  "serverStatus": "ready",
  "tools": [
    {
      "tool": "assistantUICourse",
      "description": "Teach the assistant-ui course \"Build a Generative UI Assistant\". Call with no arguments for the course overview and lesson list. Call with { \"step\": N } (1-8) to load lesson N. The response includes the full lesson markdown (instructions + code to write), the absolute path to that lesson file, focus files, and docs/example hints. Follow the lesson: explain briefly, then edit the learner's project. Use assistantUIDocs / assistantUIExamples when the lesson points to them. After finishing a lesson, ask if they want the next step and call again with step+1. On the final lesson, ask for their name and call assistantUICourseCertificate.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "step": {
            "description": "Lesson step number from 1 to 8. Omit for the course overview.",
            "type": "integer",
            "minimum": 1,
            "maximum": 8
          }
        },
        "$schema": "https://json-schema.org/draft/2020-12/schema",
        "additionalProperties": false
      }
    },
    {
      "tool": "assistantUICourseCertificate",
      "description": "Generate a local PNG completion certificate for the assistant-ui course. Ask the user what name to put on the certificate, then call with { \"name\": \"...\" }. Returns the absolute path to the saved PNG. Use after the final course lesson.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "name": {
            "type": "string",
            "description": "Recipient name to print on the certificate (required, max 80 characters)."
          }
        },
        "required": [
          "name"
        ],
        "$schema": "https://json-schema.org/draft/2020-12/schema",
        "additionalProperties": false
      }
    },
    {
      "tool": "assistantUIDocs",
      "description": "Retrieve assistant-ui documentation by path. Use \"/\" to list all sections. Supports multiple paths in a single request.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "paths": {
            "minItems": 1,
            "type": "array",
            "items": {
              "type": "string"
            },
            "description": "Documentation paths to retrieve (e.g., [\"getting-started\", \"api-reference/primitives/thread\"])"
          }
        },
        "required": [
          "paths"
        ],
        "$schema": "https://json-schema.org/draft/2020-12/schema"
      }
    },
    {
      "tool": "assistantUIExamples",
      "description": "List available examples or retrieve complete code for a specific example",
      "inputSchema": {
        "type": "object",
        "properties": {
          "example": {
            "description": "Example name (e.g., \"with-ai-sdk-v7\"). Leave empty to list all examples.",
            "type": "string"
          }
        },
        "$schema": "https://json-schema.org/draft/2020-12/schema"
      }
    },
    {
      "tool": "assistantUISearch",
      "description": "Search assistant-ui documentation by keyword. Returns ranked matches with their doc path, title, and a snippet. Fetch full content with assistantUIDocs using a returned path.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "query": {
            "type": "string",
            "minLength": 1,
            "description": "Keyword(s) to search assistant-ui documentation for."
          },
          "limit": {
            "default": 10,
            "description": "Maximum number of results to return (default 10).",
            "type": "integer",
            "minimum": 1,
            "maximum": 25
          }
        },
        "required": [
          "query"
        ],
        "$schema": "https://json-schema.org/draft/2020-12/schema"
      }
    },
    {
      "tool": "assistantUITemplateDetails",
      "description": "Get the full authoring surface for a specific assistant-ui hosted template. Returns configRoots schemas (with types, defaults, and enums), rules, built-in tool input/outputShape, renderer contracts, and an exampleConfig. Fixed demos return no configRoots; use those as-is without config. Use this before calling assistantUITemplatePreview to understand exactly what config to write. If assistantUITemplatePreview returns validationWarnings, call this again and cross-reference configRoots to correct the config.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "templateId": {
            "type": "string",
            "description": "The template id from assistantUITemplates"
          },
          "versionId": {
            "description": "Optional version id. When provided, exampleConfig reflects that version's resolved defaults.",
            "type": "string"
          }
        },
        "required": [
          "templateId"
        ],
        "$schema": "https://json-schema.org/draft/2020-12/schema"
      }
    },
    {
      "tool": "assistantUITemplatePreview",
      "description": "Return preview and download URLs for a selected assistant-ui hosted template. The previewUrl is a hosted app URL; show it to the user first, or open it with an available browser/in-app-browser tool if your client provides one. If you pass config, a preview session is created on the hosted template sandbox and the returned URLs reflect that configuration. Do not pass config for fixed demos that have no configRoots in assistantUITemplateDetails. This tool only returns URLs.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "templateId": {
            "type": "string",
            "description": "The template id from assistantUITemplates"
          },
          "versionId": {
            "description": "Version id to use. Uses the template default if omitted.",
            "type": "string"
          },
          "config": {
            "description": "Customization config for the preview. Must contain only the top-level keys: hostUi, assistant, and brandTheme. Use the schemas from assistantUITemplateDetails.configRoots as the source of truth for each root. Do not pass any other root keys.",
            "type": "object",
            "propertyNames": {
              "type": "string"
            },
            "additionalProperties": {}
          }
        },
        "required": [
          "templateId"
        ],
        "$schema": "https://json-schema.org/draft/2020-12/schema"
      }
    },
    {
      "tool": "assistantUITemplates",
      "description": "List the available assistant-ui hosted app templates and fixed demos with their features, customizable surfaces, and versions. Call this first for any assistant-ui app-building request. Use the features and customizable fields to decide which template fits. If customizable is empty, the entry is a fixed demo that should be used as-is rather than configured. Call assistantUITemplateDetails on the chosen template before requesting a preview.",
      "inputSchema": {
        "type": "object",
        "properties": {},
        "$schema": "https://json-schema.org/draft/2020-12/schema"
      }
    }
  ]
}"}}

