{"success": {"content": [{"text": {"text": "{
  "type": "example",
  "name": "with-ai-sdk-v7",
  "content": "# Example: with-ai-sdk-v7\n\n## app/api/chat/route.ts\n\n```typescript\nimport { openai } from \"@ai-sdk/openai\";\nimport { frontendTools } from \"@assistant-ui/react-ai-sdk\";\nimport {\n  type JSONSchema7,\n  streamText,\n  convertToModelMessages,\n  type UIMessage,\n  tool,\n  stepCountIs,\n  zodSchema,\n  createUIMessageStreamResponse,\n  toUIMessageStream,\n} from \"ai\";\nimport { z } from \"zod\";\n\n// Allow streaming responses up to 30 seconds\nexport const maxDuration = 30;\n\nexport async function POST(req: Request) {\n  const {\n    messages,\n    system,\n    tools,\n  }: {\n    messages: UIMessage[];\n    system?: string;\n    tools?: Record<string, { description?: string; parameters: JSONSchema7 }>;\n  } = await req.json();\n\n  const result = streamText({\n    model: openai(\"gpt-5.4-nano\"),\n    messages: await convertToModelMessages(messages),\n    ...(system ? { system } : {}),\n    stopWhen: stepCountIs(10),\n    tools: {\n      ...frontendTools(tools ?? {}),\n      get_current_weather: tool({\n        description: \"Get the current weather\",\n        inputSchema: zodSchema(\n          z.object({\n            city: z.string(),\n          }),\n        ),\n        execute: async ({ city }) => {\n          return `The weather in ${city} is sunny`;\n        },\n      }),\n    },\n  });\n\n  return createUIMessageStreamResponse({\n    stream: toUIMessageStream({ stream: result.stream }),\n  });\n}\n\n```\n\n## app/globals.css\n\n```css\n@import \"tailwindcss\";\n@import \"tw-animate-css\";\n\n@source \"../../../packages/ui/src\";\n\n@custom-variant dark (&:is(.dark *));\n\n@theme inline {\n  --radius-sm: calc(var(--radius) - 4px);\n  --radius-md: calc(var(--radius) - 2px);\n  --radius-lg: var(--radius);\n  --radius-xl: calc(var(--radius) + 4px);\n  --color-background: var(--background);\n  --color-foreground: var(--foreground);\n  --color-card: var(--card);\n  --color-card-foreground: var(--card-foreground);\n  --color-popover: var(--popover);\n  --color-popover-foreground: var(--popover-foreground);\n  --color-primary: var(--primary);\n  --color-primary-foreground: var(--primary-foreground);\n  --color-secondary: var(--secondary);\n  --color-secondary-foreground: var(--secondary-foreground);\n  --color-muted: var(--muted);\n  --color-muted-foreground: var(--muted-foreground);\n  --color-accent: var(--accent);\n  --color-accent-foreground: var(--accent-foreground);\n  --color-destructive: var(--destructive);\n  --color-border: var(--border);\n  --color-input: var(--input);\n  --color-ring: var(--ring);\n  --color-chart-1: var(--chart-1);\n  --color-chart-2: var(--chart-2);\n  --color-chart-3: var(--chart-3);\n  --color-chart-4: var(--chart-4);\n  --color-chart-5: var(--chart-5);\n  --color-sidebar: var(--sidebar);\n  --color-sidebar-foreground: var(--sidebar-foreground);\n  --color-sidebar-primary: var(--sidebar-primary);\n  --color-sidebar-primary-foreground: var(--sidebar-primary-foreground);\n  --color-sidebar-accent: var(--sidebar-accent);\n  --color-sidebar-accent-foreground: var(--sidebar-accent-foreground);\n  --color-sidebar-border: var(--sidebar-border);\n  --color-sidebar-ring: var(--sidebar-ring);\n}\n\n:root {\n  --radius: 0.625rem;\n  --background: oklch(1 0 0);\n  --foreground: oklch(0.141 0.005 285.823);\n  --card: oklch(1 0 0);\n  --card-foreground: oklch(0.141 0.005 285.823);\n  --popover: oklch(1 0 0);\n  --popover-foreground: oklch(0.141 0.005 285.823);\n  --primary: oklch(0.21 0.006 285.885);\n  --primary-foreground: oklch(0.985 0 0);\n  --secondary: oklch(0.967 0.001 286.375);\n  --secondary-foreground: oklch(0.21 0.006 285.885);\n  --muted: oklch(0.967 0.001 286.375);\n  --muted-foreground: oklch(0.552 0.016 285.938);\n  --accent: oklch(0.967 0.001 286.375);\n  --accent-foreground: oklch(0.21 0.006 285.885);\n  --destructive: oklch(0.577 0.245 27.325);\n  --border: oklch(0.92 0.004 286.32);\n  --input: oklch(0.92 0.004 286.32);\n  --ring: oklch(0.705 0.015 286.067);\n  --chart-1: oklch(0.646 0.222 41.116);\n  --chart-2: oklch(0.6 0.118 184.704);\n  --chart-3: oklch(0.398 0.07 227.392);\n  --chart-4: oklch(0.828 0.189 84.429);\n  --chart-5: oklch(0.769 0.188 70.08);\n  --sidebar: oklch(0.985 0 0);\n  --sidebar-foreground: oklch(0.141 0.005 285.823);\n  --sidebar-primary: oklch(0.21 0.006 285.885);\n  --sidebar-primary-foreground: oklch(0.985 0 0);\n  --sidebar-accent: oklch(0.967 0.001 286.375);\n  --sidebar-accent-foreground: oklch(0.21 0.006 285.885);\n  --sidebar-border: oklch(0.92 0.004 286.32);\n  --sidebar-ring: oklch(0.705 0.015 286.067);\n}\n\n.dark {\n  --background: oklch(0.141 0.005 285.823);\n  --foreground: oklch(0.985 0 0);\n  --card: oklch(0.21 0.006 285.885);\n  --card-foreground: oklch(0.985 0 0);\n  --popover: oklch(0.21 0.006 285.885);\n  --popover-foreground: oklch(0.985 0 0);\n  --primary: oklch(0.92 0.004 286.32);\n  --primary-foreground: oklch(0.21 0.006 285.885);\n  --secondary: oklch(0.274 0.006 286.033);\n  --secondary-foreground: oklch(0.985 0 0);\n  --muted: oklch(0.274 0.006 286.033);\n  --muted-foreground: oklch(0.705 0.015 286.067);\n  --accent: oklch(0.274 0.006 286.033);\n  --accent-foreground: oklch(0.985 0 0);\n  --destructive: oklch(0.704 0.191 22.216);\n  --border: oklch(1 0 0 / 10%);\n  --input: oklch(1 0 0 / 15%);\n  --ring: oklch(0.552 0.016 285.938);\n  --chart-1: oklch(0.488 0.243 264.376);\n  --chart-2: oklch(0.696 0.17 162.48);\n  --chart-3: oklch(0.769 0.188 70.08);\n  --chart-4: oklch(0.627 0.265 303.9);\n  --chart-5: oklch(0.645 0.246 16.439);\n  --sidebar: oklch(0.21 0.006 285.885);\n  --sidebar-foreground: oklch(0.985 0 0);\n  --sidebar-primary: oklch(0.488 0.243 264.376);\n  --sidebar-primary-foreground: oklch(0.985 0 0);\n  --sidebar-accent: oklch(0.274 0.006 286.033);\n  --sidebar-accent-foreground: oklch(0.985 0 0);\n  --sidebar-border: oklch(1 0 0 / 10%);\n  --sidebar-ring: oklch(0.552 0.016 285.938);\n}\n\n@layer base {\n  * {\n    @apply border-border outline-ring/50;\n  }\n  body {\n    @apply bg-background text-foreground;\n  }\n}\n\n```\n\n## app/layout.tsx\n\n```tsx\nimport type { Metadata } from \"next\";\nimport \"./globals.css\";\n\nexport const metadata: Metadata = {\n  title: \"AI SDK v7 Example\",\n  description: \"Example using @assistant-ui/react with AI SDK v7\",\n};\n\nexport default function RootLayout({\n  children,\n}: Readonly<{\n  children: React.ReactNode;\n}>) {\n  return (\n    <html lang=\"en\">\n      <body className=\"h-dvh\">{children}</body>\n    </html>\n  );\n}\n\n```\n\n## app/page.tsx\n\n```tsx\n\"use client\";\n\nimport { Thread } from \"@/components/assistant-ui/thread\";\nimport {\n  AssistantRuntimeProvider,\n  useAui,\n  AuiProvider,\n  Suggestions,\n} from \"@assistant-ui/react\";\nimport { useChatRuntime } from \"@assistant-ui/react-ai-sdk\";\n\nfunction ThreadWithSuggestions() {\n  const aui = useAui({\n    suggestions: Suggestions([\n      {\n        title: \"What's the weather\",\n        label: \"in Tokyo right now?\",\n        prompt: \"What's the weather in Tokyo?\",\n      },\n      {\n        title: \"Tell me a fun fact\",\n        label: \"about any topic\",\n        prompt: \"Tell me a fun fact about space.\",\n      },\n    ]),\n  });\n  return (\n    <AuiProvider value={aui}>\n      <Thread />\n    </AuiProvider>\n  );\n}\n\nexport default function Home() {\n  const runtime = useChatRuntime();\n\n  return (\n    <AssistantRuntimeProvider runtime={runtime}>\n      <div className=\"h-full\">\n        <ThreadWithSuggestions />\n      </div>\n    </AssistantRuntimeProvider>\n  );\n}\n\n```\n\n## components.json\n\n```json\n{\n  \"$schema\": \"https://ui.shadcn.com/schema.json\",\n  \"style\": \"new-york\",\n  \"rsc\": true,\n  \"tsx\": true,\n  \"tailwind\": {\n    \"config\": \"\",\n    \"css\": \"app/globals.css\",\n    \"baseColor\": \"zinc\",\n    \"cssVariables\": true,\n    \"prefix\": \"\"\n  },\n  \"aliases\": {\n    \"components\": \"@/components\",\n    \"utils\": \"@/lib/utils\",\n    \"ui\": \"@/components/ui\",\n    \"lib\": \"@/lib\",\n    \"hooks\": \"@/hooks\"\n  },\n  \"iconLibrary\": \"lucide\",\n  \"registries\": {\n    \"@assistant-ui\": \"https://r.assistant-ui.com/{name}.json\"\n  }\n}\n\n```\n\n## next.config.js\n\n```javascript\nimport { withAui } from \"@assistant-ui/next\";\n/** @type {import('next').NextConfig} */\nconst nextConfig = {\n  transpilePackages: [\"@assistant-ui/react\", \"@assistant-ui/react-ai-sdk\"],\n};\n\nexport default withAui(nextConfig);\n\n```\n\n## package.json\n\n```json\n{\n  \"name\": \"with-ai-sdk-v7\",\n  \"version\": \"0.0.0\",\n  \"private\": true,\n  \"type\": \"module\",\n  \"scripts\": {\n    \"dev\": \"next dev\",\n    \"build\": \"next build\",\n    \"start\": \"next start\"\n  },\n  \"dependencies\": {\n    \"@ai-sdk/openai\": \"^4.0.14\",\n    \"@assistant-ui/react\": \"workspace:*\",\n    \"@assistant-ui/react-ai-sdk\": \"workspace:*\",\n    \"@assistant-ui/react-markdown\": \"workspace:*\",\n    \"@assistant-ui/ui\": \"workspace:*\",\n    \"ai\": \"^7.0.28\",\n    \"class-variance-authority\": \"^0.7.1\",\n    \"clsx\": \"^2.1.1\",\n    \"lucide-react\": \"^1.24.0\",\n    \"next\": \"^16.2.10\",\n    \"react\": \"^19.2.7\",\n    \"react-dom\": \"^19.2.7\",\n    \"tailwind-merge\": \"^3.6.0\",\n    \"zod\": \"^4.4.3\"\n  },\n  \"devDependencies\": {\n    \"@assistant-ui/next\": \"workspace:*\",\n    \"@assistant-ui/x-buildutils\": \"workspace:*\",\n    \"@tailwindcss/postcss\": \"^4.3.2\",\n    \"@types/node\": \"^26.1.1\",\n    \"@types/react\": \"^19.2.17\",\n    \"@types/react-dom\": \"^19.2.3\",\n    \"postcss\": \"^8.5.19\",\n    \"tailwindcss\": \"^4.3.2\",\n    \"tw-animate-css\": \"^1.4.0\",\n    \"typescript\": \"npm:@typescript/typescript6@^6.0.2\",\n    \"typescript-7\": \"npm:typescript@^7.0.2\"\n  }\n}\n\n```\n\n## README.md\n\n```markdown\n# AI SDK v7 Example\n\nThis example demonstrates how to use `@assistant-ui/react-ai-sdk` with the Vercel AI SDK v7.\n\n## Quick Start\n\n### Using CLI (Recommended)\n\n```bash\nnpx assistant-ui@latest create my-app --example with-ai-sdk-v7\ncd my-app\n```\n\n### Environment Variables\n\nCreate `.env.local`:\n\n```sh\nOPENAI_API_KEY=your-api-key-here\n```\n\n### Run\n\n```bash\npnpm install\npnpm dev\n```\n\nOpen [http://localhost:3000](http://localhost:3000) to see the result.\n\n## Key Features\n\n- Uses the new AI SDK v7 with `@ai-sdk/openai`\n- Integrates with `@assistant-ui/react` using the new `useChatRuntime` hook\n- No RSC support (client-side only)\n- Simplified integration with the `useChatRuntime` hook that wraps AI SDK v7's `useChat`\n- Uses `AssistantChatTransport` to pass system messages and frontend tools to the backend\n\n## Custom Transport Configuration\n\nBy default, `useChatRuntime` uses `AssistantChatTransport` which automatically forwards system messages and frontend tools to the backend.\n\n### Custom API URL with Forwarding\n\nWhen customizing the API URL, you must explicitly use `AssistantChatTransport` to keep system/tools forwarding:\n\n```typescript\nimport { AssistantChatTransport } from \"@assistant-ui/react-ai-sdk\";\n\nconst runtime = useChatRuntime({\n  transport: new AssistantChatTransport({\n    api: \"/my-custom-api/chat\", // Custom URL with system/tools forwarding\n  }),\n});\n```\n\n### Disable System/Tools Forwarding\n\nTo use the standard AI SDK transport without forwarding:\n\n```typescript\nimport { DefaultChatTransport } from \"ai\";\n\nconst runtime = useChatRuntime({\n  transport: new DefaultChatTransport(), // No system/tools forwarding\n});\n```\n\n## API Route\n\nThe API route at `/api/chat` uses AI SDK v7 `streamText`, forwards `system` and frontend `tools`, and merges them with a server-defined weather tool.\n\n## Related Documentation\n\n- [assistant-ui Documentation](https://www.assistant-ui.com/docs)\n- [AI SDK Integration Guide](https://www.assistant-ui.com/docs/runtimes/ai-sdk)\n\n```\n\n## tsconfig.json\n\n```json\n{\n  \"extends\": \"@assistant-ui/x-