  "content": "# Example: with-store\n\n## app/globals.css\n\n```css\n@import \"tailwindcss\";\n\n:root {\n  --background: #ffffff;\n  --foreground: #171717;\n}\n\n@theme inline {\n  --color-background: var(--background);\n  --color-foreground: var(--foreground);\n  --font-sans: var(--font-geist-sans);\n  --font-mono: var(--font-geist-mono);\n}\n\n@media (prefers-color-scheme: dark) {\n  :root {\n    --background: #0a0a0a;\n    --foreground: #ededed;\n  }\n}\n\nbody {\n  background: var(--background);\n  color: var(--foreground);\n  font-family: Arial, Helvetica, sans-serif;\n}\n\n```\n\n## app/layout.tsx\n\n```tsx\nimport type { Metadata } from \"next\";\nimport { Geist, Geist_Mono } from \"next/font/google\";\nimport \"./globals.css\";\n\nconst geistSans = Geist({\n  variable: \"--font-geist-sans\",\n  subsets: [\"latin\"],\n});\n\nconst geistMono = Geist_Mono({\n  variable: \"--font-geist-mono\",\n  subsets: [\"latin\"],\n});\n\nexport const metadata: Metadata = {\n  title: \"Create Next App\",\n  description: \"Generated by create next app\",\n};\n\nexport default function RootLayout({\n  children,\n}: Readonly<{\n  children: React.ReactNode;\n}>) {\n  return (\n    <html lang=\"en\">\n      <body\n        className={`${geistSans.variable} ${geistMono.variable} antialiased`}\n      >\n        {children}\n      </body>\n    </html>\n  );\n}\n\n```\n\n## app/page.tsx\n\n```tsx\nimport { ExampleApp } from \"@/lib/example-app\";\n\nexport default function Home() {\n  return (\n    <div className=\"min-h-screen bg-linear-to-br from-gray-50 to-gray-100 p-8 dark:from-gray-900 dark:to-gray-800\">\n      <div className=\"mx-auto max-w-4xl\">\n        <div className=\"mb-8\">\n          <h1 className=\"mb-2 text-4xl font-bold text-gray-900 dark:text-white\">\n            @assistant-ui/store Example\n          </h1>\n          <p className=\"text-lg text-gray-600 dark:text-gray-400\">\n            Demonstrating tap-based state management with scopes, lists, and\n            providers\n          </p>\n        </div>\n\n        <ExampleApp />\n      </div>\n    </div>\n  );\n}\n\n```\n\n## lib/example-app.tsx\n\n```tsx\n\"use client\";\n\nimport { useState } from \"react\";\nimport {\n  useAui,\n  AuiProvider,\n  useAuiState,\n  useAuiEvent,\n} from \"@assistant-ui/store\";\nimport { FooList, FooListResource } from \"./store/foo-store\";\n\n/**\n * Single Foo component - displays and allows editing a single foo\n */\nconst Foo = () => {\n  const aui = useAui();\n  const fooId = useAuiState((s) => s.foo.id);\n  const fooBar = useAuiState((s) => s.foo.bar);\n\n  // Each foo logs its own events - only receives events from THIS foo instance\n  useAuiEvent(\"foo.updated\", (payload) => {\n    console.log(`[${fooId}] Updated to: ${payload.newValue}`);\n  });\n\n  const handleUpdate = () => {\n    aui.foo().updateBar(`Updated at ${new Date().toLocaleTimeString()}`);\n  };\n\n  return (\n    <div className=\"rounded-lg border border-gray-200 bg-white p-6 shadow-md transition-shadow hover:shadow-lg dark:border-gray-700 dark:bg-gray-800\">\n      <div className=\"space-y-3\">\n        <div className=\"flex items-center gap-2\">\n          <span className=\"text-sm font-semibold text-gray-500 dark:text-gray-400\">\n            ID:\n          </span>\n          <span className=\"font-mono text-sm text-gray-900 dark:text-white\">\n            {fooId}\n          </span>\n        </div>\n        <div className=\"flex items-center gap-2\">\n          <span className=\"text-sm font-semibold text-gray-500 dark:text-gray-400\">\n            Value:\n          </span>\n          <span className=\"text-gray-900 dark:text-white\">{fooBar}</span>\n        </div>\n        <div className=\"mt-2 flex gap-2\">\n          <button\n            type=\"button\"\n            onClick={handleUpdate}\n            className=\"flex-1 rounded-md bg-blue-600 px-4 py-2 font-medium text-white transition-colors hover:bg-blue-700 focus:ring-2 focus:ring-blue-500 focus:ring-offset-2 focus:outline-none dark:focus:ring-offset-gray-800\"\n          >\n            Update\n          </button>\n          <button\n            type=\"button\"\n            onClick={() => aui.foo().remove()}\n            className=\"rounded-md bg-red-600 px-4 py-2 font-medium text-white transition-colors hover:bg-red-700 focus:ring-2 focus:ring-red-500 focus:ring-offset-2 focus:outline-none dark:focus:ring-offset-gray-800\"\n          >\n            Delete\n          </button>\n        </div>\n      </div>\n    </div>\n  );\n};\n\nconst FooListLength = () => {\n  const fooListLength = useAuiState((s) => s.fooList.foos.length);\n  return (\n    <span className=\"text-gray-500 dark:text-gray-400\">\n      ({fooListLength} items)\n    </span>\n  );\n};\n\nconst AddFooButton = () => {\n  const aui = useAui();\n  return (\n    <button\n      type=\"button\"\n      onClick={() => aui.fooList().addFoo()}\n      className=\"rounded-md bg-green-600 px-4 py-2 font-medium text-white transition-colors hover:bg-green-700 focus:ring-2 focus:ring-green-500 focus:ring-offset-2 focus:outline-none dark:focus:ring-offset-gray-800\"\n    >\n      Add New\n    </button>\n  );\n};\n\ntype EventLogEntry = {\n  id: number;\n  event: string;\n  payload: unknown;\n  timestamp: Date;\n};\n\nlet idCounter = 0;\n/**\n * EventLog component - demonstrates event subscription\n */\nconst EventLog = () => {\n  const [logs, setLogs] = useState<EventLogEntry[]>([]);\n\n  // Subscribe to all events using the wildcard selector\n  useAuiEvent(\"*\", (data) => {\n    setLogs((prev) => [\n      {\n        id: ++idCounter,\n        event: data.event,\n        payload: data.payload,\n        timestamp: new Date(),\n      },\n      ...prev.slice(0, 9), // Keep last 10 entries\n    ]);\n  });\n\n  return (\n    <div className=\"rounded-lg border border-gray-200 bg-white p-4 shadow-sm dark:border-gray-700 dark:bg-gray-800\">\n      <h3 className=\"mb-3 font-semibold text-gray-900 dark:text-white\">\n        Event Log\n      </h3>\n      <div className=\"max-h-48 space-y-2 overflow-y-auto\">\n        {logs.length === 0 ? (\n          <p className=\"text-sm text-gray-500 dark:text-gray-400\">\n            No events yet. Try updating or deleting a foo.\n          </p>\n        ) : (\n          logs.map((log) => (\n            <div\n              key={log.id}\n              className=\"rounded border border-gray-100 bg-gray-50 p-2 font-mono text-xs dark:border-gray-600 dark:bg-gray-700\"\n            >\n              <span className=\"font-semibold text-blue-600 dark:text-blue-400\">\n                {log.event}\n              </span>\n              <span className=\"ml-2 text-gray-600 dark:text-gray-300\">\n                {JSON.stringify(log.payload)}\n              </span>\n              <span className=\"ml-2 text-gray-400 dark:text-gray-500\">\n                {log.timestamp.toLocaleTimeString()}\n              </span>\n            </div>\n          ))\n        )}\n      </div>\n    </div>\n  );\n};\n\n/**\n * Example App - demonstrates the store with styled components\n *\n * Note: The fooList scope is also registered in foo-scope.ts as a default,\n * but we're explicitly passing it here for clarity in the example.\n */\nexport const ExampleApp = () => {\n  const aui = useAui({\n    fooList: FooListResource({ initialValues: true }),\n  });\n\n  return (\n    <AuiProvider value={aui}>\n      <div className=\"space-y-6\">\n        <div className=\"rounded-lg border border-gray-200 bg-white p-4 shadow-sm dark:border-gray-700 dark:bg-gray-800\">\n          <div className=\"flex items-center justify-between\">\n            <h2 className=\"text-xl font-semibold text-gray-900 dark:text-white\">\n              Foo List <FooListLength />\n            </h2>\n            <AddFooButton />\n          </div>\n          <p className=\"mt-1 text-sm text-gray-600 dark:text-gray-400\">\n            Each item is rendered in its own FooProvider with scoped access\n          </p>\n        </div>\n        <div className=\"grid gap-4 md:grid-cols-2 lg:grid-cols-3\">\n          <FooList>{() => <Foo />}</FooList>\n        </div>\n        <EventLog />\n      </div>\n    </AuiProvider>\n  );\n};\n\n```\n\n## lib/store/foo-scope.ts\n\n```typescript\nimport \"@assistant-ui/store\";\n\ntype FooState = { id: string; bar: string };\ntype FooMethods = {\n  getState: () => FooState;\n  updateBar: (newBar: string) => void;\n  remove: () => void;\n};\ntype FooMeta = {\n  source: \"fooList\";\n  query: { index: number } | { key: string };\n};\ntype FooEvents = {\n  \"foo.updated\": { id: string; newValue: string };\n  \"foo.removed\": { id: string };\n};\n\ntype FooListState = { foos: FooState[] };\ntype FooListMethods = {\n  getState: () => FooListState;\n  foo: (lookup: FooMeta[\"query\"]) => FooMethods;\n  addFoo: () => void;\n};\ntype FooListEvents = {\n  \"fooList.added\": { id: string };\n};\n\ndeclare module \"@assistant-ui/store\" {\n  interface ScopeRegistry {\n    foo: {\n      methods: FooMethods;\n      meta: FooMeta;\n      events: FooEvents;\n    };\n    fooList: {\n      methods: FooListMethods;\n      events: FooListEvents;\n    };\n  }\n}\n\n```\n\n## lib/store/foo-store.tsx\n\n```tsx\n\"use client\";\n\nimport \"./foo-scope\";\n\nimport { type ReactNode, useMemo, useState } from \"react\";\nimport { resource } from \"@assistant-ui/tap\";\nimport {\n  useAui,\n  useAuiState,\n  AuiProvider,\n  useClientList,\n  Derived,\n  useAssistantEmit,\n  RenderChildrenWithAccessor,\n  type ClientOutput,\n} from \"@assistant-ui/store\";\n\ntype FooData = { id: string; bar: string };\n\nconst useFooItemResource = ({\n  getInitialData,\n  remove,\n}: useClientList.ResourceProps<FooData>): ClientOutput<\"foo\"> => {\n  const emit = useAssistantEmit();\n\n  const [state, setState] = useState<FooData>(getInitialData);\n\n  const updateBar = (newBar: string) => {\n    setState({ ...state, bar: newBar });\n    emit(\"foo.updated\", { id: state.id, newValue: newBar });\n  };\n\n  const handleRemove = () => {\n    emit(\"foo.removed\", { id: state.id });\n    remove();\n  };\n\n  return {\n    getState: () => state,\n    updateBar,\n    remove: handleRemove,\n  };\n};\n\nexport const FooItemResource = resource(useFooItemResource);\n\nlet counter = 3;\nconst useFooListResource = ({\n  initialValues,\n}: {\n  initialValues: boolean;\n}): ClientOutput<\"fooList\"> => {\n  const emit = useAssistantEmit();\n\n  const foos = useClientList({\n    initialValues: initialValues\n      ? [\n          { id: \"foo-1\", bar: \"First Foo\" },\n          { id: \"foo-2\", bar: \"Second Foo\" },\n          { id: \"foo-3\", bar: \"Third Foo\" },\n        ]\n      : [],\n    getKey: (foo) => foo.id,\n    resource: FooItemResource,\n  });\n\n  const addFoo = () => {\n    const id = `foo-${++counter}`;\n    foos.add({ id: id, bar: `New Foo` });\n    emit(\"fooList.added\", { id: id });\n  };\n\n  const state = useMemo(() => ({ foos: foos.state }), [foos.state]);\n\n  return {\n    getState: () => state,\n    foo: foos.get,\n    addFoo,\n  };\n};\n\nexport const FooListResource = resource(useFooListResource);\n\nconst FooProvider = ({\n  index,\n  children,\n}: {\n  index: number;\n  children: ReactNode;\n}) => {\n  const aui = useAui({\n    foo: Derived({\n      source: \"fooList\",\n      query: { index },\n      get: (aui) => aui.fooList().foo({ index }),\n    }),\n  });\n\n  return <AuiProvider value={aui}>{children}</AuiProvider>;\n};\n\nexport const FooList = ({\n  children,\n}: {\n  children: (item: { foo: FooData }) => ReactNode;\n}) => {\n  const length = useAuiState((s) => s.fooList.foos.length);\n\n  return useMemo(\n    () =>\n      Array.from({ length }, (_, index) => (\n        <FooProvider key={index} index={index}>\n          <RenderChildrenWithAccessor\n            getItemState={(aui) => aui.fooList().foo({ index }).getState()}\n          >\n            {(getItem) =>\n              children({\n                get foo() {\n                  return getItem();\n                },\n              })\n            }\n          </RenderChildrenWithAccessor>\n        </FooProvider>\n      )),\n    [length, children],\n  );\n};\n\n```\n\n## next.config.ts\n\n```typescript\nimport { withAui } from \"@assistant-ui/next\";\nimport type { NextConfig } from \"next\";\n\nconst nextConfig: NextConfig = {/* config options here */};\n\nexport default withAui(nextConfig);\n\n```\n\n## package.json\n\n```json\n{\n  \"name\": \"with-store\",\n  \"version\": \"0.0.0\",\n  \"private\": true,\n  \"type\": \"module\",\n  \"scripts\": {\n    \"dev\": \"next dev\",\n    \"build\": \"next build\",\n    \"start\": \"next start\"\n  },\n  \"dependencies\": {\n    \"@assistant-ui/store\": \"workspace:*\",\n    \"@assistant-ui/tap\": \"workspace:*\",\n    \"next\": \"^16.2.10\",\n    \"react\": \"^19.2.7\",\n    \"react-dom\": \"^19.2.7\"\n  },\n  \"devDependencies\": {\n    \"@assistant-ui/next\": \"workspace:*\",\n    \"@assistant-ui/x-buildutils\": \"workspace:*\",\n    \"@tailwindcss/postcss\": \"^4.3.2\",\n    \"@types/node\": \"^26.1.1\",\n    \"@types/react\": \"^19.2.17\",\n    \"@types/react-dom\": \"^19.2.3\",\n    \"postcss\": \"^8.5.19\",\n    \"tailwindcss\": \"^4.3.2\",\n    \"tw-animate-css\": \"^1.4.0\",\n    \"typescript\": \"npm:@typescript/typescript6@^6.0.2\",\n    \"typescript-7\": \"npm:typescript@^7.0.2\"\n  }\n}\n\n```\n\n## README.md\n\n```markdown\n# @assistant-ui/store Example App\n\nThis is a Next.js application demonstrating the `@assistant-ui/store` package.\n\n## Features Demonstrated\n\n- **Client Registry**: Module augmentation for type-safe client definitions\n- **useClientList**: Managing lists with index and key lookup\n- **useAssistantEmit**: Emitting and subscribing to scoped events\n- **Derived**: Creating derived client scopes from parent resources\n- **Provider Pattern**: Scoped access to list items via FooProvider\n- **Component Composition**: Render props pattern with components prop\n\n## Getting Started\n\n```bash\n# Install dependencies (from monorepo root)\npnpm install\n\n# Run the development server\ncd examples/store-example\npnpm dev\n```\n\nOpen [http://localhost:3000](http://localhost:3000) to see the example.\n\n## Project Structure\n\n- `lib/store/foo-scope.ts` - Type definitions via module augmentation:\n  - Client registry definitions (foo, fooList)\n  - State, methods, meta, and events types\n- `lib/store/foo-store.tsx` - Store implementation with:\n  - Resource implementations (FooItemResource, FooListResource)\n  - Provider component (FooProvider)\n  - FooList mapping component\n- `lib/example-app.tsx` - Example app with styled components:\n  - Foo component with update/delete actions\n  - EventLog component demonstrating event subscriptions\n  - ExampleApp with layout and styling\n- `app/page.tsx` - Main page that renders the ExampleApp\n\n## Key Concepts\n\n### Client Registry\n\n```typescript\ndeclare module \"@assistant-ui/store\" {\n  interface ScopeRegistry {\n    foo: {\n      state: { id: string; bar: string };\n      methods: {\n        getState: () => FooState;\n        updateBar: (newBar: string) => void;\n        remove: () => void;\n      };\n      meta: {\n        source: \"fooList\";\n        query: { index: number } | { key: string };\n      };\n      events: {\n        \"foo.updated\": { id: string; newValue: string };\n        \"foo.removed\": { id: string };\n      };\n    };\n  }\n}\n```\n\n### Resource Implementation\n\n```typescript\nconst FooListResource = resource(\n  function FooListResource({ initialValues }): ClientOutput<\"fooList\"> {\n    const emit = useAssistantEmit();\n\n    const foos = useClientList({\n      initialValues: initialValues ? [/* ... */] : [],\n      getKey: (foo) => foo.id,\n      resource: FooItemResource,\n    });\n\n    return {\n      state: { foos: foos.state },\n      methods: {\n        getState: () => state,\n        foo: foos.get,\n        addFoo: () => { /* ... */ },\n      },\n    };\n  },\n);\n```\n\n### Provider Pattern with Derived\n\n```typescript\nconst FooProvider = ({ index, children }) => {\n  const aui = useAui({\n    foo: Derived({\n      source: \"fooList\",\n      query: { index },\n      get: (aui) => aui.fooList().foo({ index }),\n    }),\n  });\n  return <AuiProvider value={aui}>{children}</AuiProvider>;\n};\n```\n\n### Event Subscriptions\n\n```typescript\n// Subscribe to specific events within a scope\nuseAuiEvent(\"foo.updated\", (payload) => {\n  console.log(`Updated to: ${payload.newValue}`);\n});\n\n// Subscribe to all events using wildcard\nuseAuiEvent(\"*\", (data) => {\n  console.log(data.event, data.payload);\n});\n```\n\n## Learn More\n\n- [@assistant-ui/store Documentation](https://github.com/assistant-ui/assistant-ui/tree/main/packages/store)\n- [Next.js Documentation](https://nextjs.org/docs)\n\n```\n\n## tsconfig.json\n\n```json\n{\n  \"extends\": \"@assistant-ui/x-buildutils/ts/next\",\n  \"compilerOptions\": {\n    \"paths\": {\n      \"@/*\": [\"./*\"]\n    },\n    \"allowJs\": true,\n    \"incremental\": true,\n    \"jsx\": \"preserve\"\n  },\n  \"include\": [\"**/*.ts\", \"**/*.tsx\", \".next/types/**/*.ts\"],\n  \"exclude\": [\"node_modules\"]\n}\n\n```\n\n"
