7 0.001 286.375);\n  --sidebar-accent-foreground: oklch(0.21 0.006 285.885);\n  --sidebar-border: oklch(0.92 0.004 286.32);\n  --sidebar-ring: oklch(0.705 0.015 286.067);\n}\n\n.dark {\n  --background: oklch(0.141 0.005 285.823);\n  --foreground: oklch(0.985 0 0);\n  --card: oklch(0.21 0.006 285.885);\n  --card-foreground: oklch(0.985 0 0);\n  --popover: oklch(0.21 0.006 285.885);\n  --popover-foreground: oklch(0.985 0 0);\n  --primary: oklch(0.92 0.004 286.32);\n  --primary-foreground: oklch(0.21 0.006 285.885);\n  --secondary: oklch(0.274 0.006 286.033);\n  --secondary-foreground: oklch(0.985 0 0);\n  --muted: oklch(0.274 0.006 286.033);\n  --muted-foreground: oklch(0.705 0.015 286.067);\n  --accent: oklch(0.274 0.006 286.033);\n  --accent-foreground: oklch(0.985 0 0);\n  --destructive: oklch(0.704 0.191 22.216);\n  --border: oklch(1 0 0 / 10%);\n  --input: oklch(1 0 0 / 15%);\n  --ring: oklch(0.552 0.016 285.938);\n  --chart-1: oklch(0.488 0.243 264.376);\n  --chart-2: oklch(0.696 0.17 162.48);\n  --chart-3: oklch(0.769 0.188 70.08);\n  --chart-4: oklch(0.627 0.265 303.9);\n  --chart-5: oklch(0.645 0.246 16.439);\n  --sidebar: oklch(0.21 0.006 285.885);\n  --sidebar-foreground: oklch(0.985 0 0);\n  --sidebar-primary: oklch(0.488 0.243 264.376);\n  --sidebar-primary-foreground: oklch(0.985 0 0);\n  --sidebar-accent: oklch(0.274 0.006 286.033);\n  --sidebar-accent-foreground: oklch(0.985 0 0);\n  --sidebar-border: oklch(1 0 0 / 10%);\n  --sidebar-ring: oklch(0.552 0.016 285.938);\n}\n\n@layer base {\n  * {\n    @apply border-border outline-ring/50;\n  }\n  body {\n    @apply bg-background text-foreground;\n  }\n}\n\n```\n\n## app/layout.tsx\n\n```tsx\nimport type { Metadata } from \"next\";\nimport \"./globals.css\";\nimport { MyRuntimeProvider } from \"./MyRuntimeProvider\";\n\nexport const metadata: Metadata = {\n  title: \"Custom Thread List Example\",\n  description:\n    \"Example using @assistant-ui/react with a custom thread list adapter\",\n};\n\nexport default function RootLayout({\n  children,\n}: Readonly<{\n  children: React.ReactNode;\n}>) {\n  return (\n    <html lang=\"en\" className=\"h-dvh\">\n      <body className=\"h-dvh antialiased\">\n        <MyRuntimeProvider>{children}</MyRuntimeProvider>\n      </body>\n    </html>\n  );\n}\n\n```\n\n## app/MyRuntimeProvider.tsx\n\n```tsx\n\"use client\";\n\nimport type { ReactNode } from \"react\";\nimport {\n  AssistantRuntimeProvider,\n  useRemoteThreadListRuntime,\n  type RemoteThreadListAdapter,\n} from \"@assistant-ui/react\";\nimport { useChatRuntime } from \"@assistant-ui/react-ai-sdk\";\nimport { createAssistantStream } from \"assistant-stream\";\n\nconst PAGE_SIZE = 10;\n\nconst threadsStore = new Map<\n  string,\n  {\n    remoteId: string;\n    status: \"regular\" | \"archived\";\n    title?: string;\n  }\n>(\n  Array.from({ length: 25 }, (_, i) => {\n    const id = `seed-${String(i).padStart(2, \"0\")}`;\n    return [\n      id,\n      {\n        remoteId: id,\n        status: \"regular\" as const,\n        title: `Seeded thread ${i + 1}`,\n      },\n    ] as const;\n  }),\n);\n\nconst threadListAdapter: RemoteThreadListAdapter = {\n  async list({ after }: { after?: string } = {}) {\n    const all = Array.from(threadsStore.values());\n    const start = after ? Number(after) : 0;\n    const page = all.slice(start, start + PAGE_SIZE);\n    const nextStart = start + page.length;\n    return {\n      threads: page.map((thread) => ({\n        remoteId: thread.remoteId,\n        status: thread.status,\n        title: thread.title,\n      })),\n      nextCursor: nextStart < all.length ? String(nextStart) : undefined,\n    };\n  },\n\n  async initialize(localId) {\n    const remoteId = localId;\n    threadsStore.set(remoteId, {\n      remoteId,\n      status: \"regular\",\n    });\n    return { remoteId, externalId: undefined };\n  },\n\n  async rename(remoteId, title) {\n    const thread = threadsStore.get(remoteId);\n    if (thread) {\n      thread.title = title;\n    }\n  },\n\n  async archive(remoteId) {\n    const thread = threadsStore.get(remoteId);\n    if (thread) {\n      thread.status = \"archived\";\n    }\n  },\n\n  async unarchive(remoteId) {\n    const thread = threadsStore.get(remoteId);\n    if (thread) {\n      thread.status = \"regular\";\n    }\n  },\n\n  async delete(remoteId) {\n    threadsStore.delete(remoteId);\n  },\n\n  async fetch(remoteId) {\n    const thread = threadsStore.get(remoteId);\n    if (!thread) {\n      throw new Error(\"Thread not found\");\n    }\n    return {\n      remoteId: thread.remoteId,\n      status: thread.status,\n      title: thread.title,\n    };\n  },\n\n  async generateTitle(_remoteId, messages) {\n    // Generate a simple title from the first user message\n    return createAssistantStream(async (controller) => {\n      const firstUserMessage = messages.find((m) => m.role === \"user\");\n      if (firstUserMessage) {\n        const content = firstUserMessage.content\n          .filter((c) => c.type === \"text\")\n          .map((c) => c.text)\n          .join(\" \");\n        const title = content.slice(0, 50) + (content.length > 50 ? \"...\" : \"\");\n        controller.appendText(title);\n      } else {\n        controller.appendText(\"New Chat\");\n      }\n    });\n  },\n};\n\nexport function MyRuntimeProvider({\n  children,\n}: Readonly<{ children: ReactNode }>) {\n  const runtime = useRemoteThreadListRuntime({\n    runtimeHook: useChatRuntime,\n    adapter: threadListAdapter,\n  });\n\n  return (\n    <AssistantRuntimeProvider runtime={runtime}>\n      {children}\n    </AssistantRuntimeProvider>\n  );\n}\n\n```\n\n## app/page.tsx\n\n```tsx\n\"use client\";\n\nimport { Thread } from \"@/components/assistant-ui/thread\";\nimport {\n  AuiProvider,\n  Suggestions,\n  ThreadListItemPrimitive,\n  ThreadListPrimitive,\n  useAui,\n} from \"@assistant-ui/react\";\n\nfunction ThreadList() {\n  return (\n    <ThreadListPrimitive.Root className=\"flex flex-col gap-1 overflow-y