export type StoredThread = {
  remoteId: string;
  status: "regular" | "archived";
  title?: string;
  lastMessageAt?: string;
  createdAt: string;
};

export type StoredMessage = {
  id: string;
  parent_id: string | null;
  format: string;
  content: Record<string, unknown>;
};

const THREADS_KEY = "aui-chat:threads";

const messagesKey = (threadId: string) => `aui-chat:messages:${threadId}`;

const readJson = <T>(key: string, fallback: T): T => {
  if (typeof window === "undefined") return fallback;
  try {
    const raw = window.localStorage.getItem(key);
    if (!raw) return fallback;
    return JSON.parse(raw) as T;
  } catch {
    return fallback;
  }
};

const writeJson = (key: string, value: unknown) => {
  if (typeof window === "undefined") return;
  window.localStorage.setItem(key, JSON.stringify(value));
};

export const loadThreads = (): StoredThread[] =>
  readJson<StoredThread[]>(THREADS_KEY, []);

export const saveThreads = (threads: StoredThread[]) => {
  writeJson(THREADS_KEY, threads);
};

export const loadMessages = (threadId: string): StoredMessage[] =>
  readJson<StoredMessage[]>(messagesKey(threadId), []);

export const saveMessages = (threadId: string, messages: StoredMessage[]) => {
  writeJson(messagesKey(threadId), messages);
};

export const deleteMessages = (threadId: string) => {
  if (typeof window === "undefined") return;
  window.localStorage.removeItem(messagesKey(threadId));
};

"use client";

import {
  RuntimeAdapterProvider,
  useAui,
  type RemoteThreadListAdapter,
  type ThreadHistoryAdapter,
} from "@assistant-ui/react";
import { createAssistantStream } from "assistant-stream";
import { useMemo } from "react";
import {
  deleteMessages,
  loadMessages,
  loadThreads,
  saveMessages,
  saveThreads,
  type StoredMessage,
  type StoredThread,
} from "./storage";

const sortThreads = (threads: StoredThread[]) =>
  [...threads].sort((a, b) => {
    const aTime = new Date(a.lastMessageAt ?? a.createdAt).getTime();
    const bTime = new Date(b.lastMessageAt ?? b.createdAt).getTime();
    return bTime - aTime;
  });

const upsertThread = (
  remoteId: string,
  patch: Partial<Omit<StoredThread, "remoteId" | "createdAt">>,
) => {
  const threads = loadThreads();
  const index = threads.findIndex((thread) => thread.remoteId === remoteId);
  if (index === -1) {
    const createdAt = new Date().toISOString();
    threads.push({
      remoteId,
      status: "regular",
      createdAt,
      ...patch,
    });
  } else {
    threads[index] = { ...threads[index], ...patch };
  }
  saveThreads(sortThreads(threads));
};

const toRemoteThread = (thread: StoredThread) => ({
  remoteId: thread.remoteId,
  status: thread.status,
  title: thread.title,
  lastMessageAt: thread.lastMessageAt
    ? new Date(thread.lastMessageAt)
    : undefined,
});

export const threadListAdapter: RemoteThreadListAdapter = {
  async list() {
    const threads = loadThreads().filter((thread) => thread.status === "regular");
    return {
      threads: sortThreads(threads).map(toRemoteThread),
    };
  },

  async initialize(threadId) {
    upsertThread(threadId, { status: "regular" });
    return { remoteId: threadId, externalId: undefined };
  },

  async rename(remoteId, title) {
    upsertThread(remoteId, { title });
  },

  async archive(remoteId) {
    upsertThread(remoteId, { status: "archived" });
  },

  async unarchive(remoteId) {
    upsertThread(remoteId, { status: "regular" });
  },

  async delete(remoteId) {
    const threads = loadThreads().filter((thread) => thread.remoteId !== remoteId);
    saveThreads(threads);
    deleteMessages(remoteId);
  },

  async fetch(remoteId) {
    const thread = loadThreads().find((item) => item.remoteId === remoteId);
    if (!thread) {
      throw new Error(`Thread "${remoteId}" not found.`);
    }
    return toRemoteThread(thread);
  },

  async generateTitle(_remoteId, messages) {
    return createAssistantStream(async (controller) => {
      const firstUserMessage = messages.find((message) => message.role === "user");
      if (!firstUserMessage) {
        controller.appendText("New Chat");
        return;
      }

      const content = firstUserMessage.content
        .filter((part) => part.type === "text")
        .map((part) => part.text)
        .join(" ")
        .trim();

      const title =
        content.length > 50 ? `${content.slice(0, 50).trimEnd()}...` : content;
      controller.appendText(title || "New Chat");
    });
  },

  unstable_Provider({ children }) {
    const aui = useAui();
    const history = useMemo<ThreadHistoryAdapter>(
      () => ({
        async load() {
          return { messages: [] };
        },
        async append() {},
        withFormat: (fmt) => ({
          async load() {
            const { remoteId } = aui.threadListItem.getState();
            if (!remoteId) return { messages: [] };

            const rows = loadMessages(remoteId);
            return {
              messages: rows.map((row) =>
                fmt.decode({
                  id: row.id,
                  parent_id: row.parent_id,
                  format: row.format,
                  content: row.content,
                }),
              ),
            };
          },
          async append(item) {
            const { remoteId } = await aui.threadListItem.initialize();
            const rows = loadMessages(remoteId);
            const row: StoredMessage = {
              id: fmt.getId(item.message),
              parent_id: item.parentId,
              format: fmt.format,
              content: fmt.encode(item),
            };

            const existingIndex = rows.findIndex((entry) => entry.id === row.id);
            if (existingIndex === -1) {
              rows.push(row);
            } else {
              rows[existingIndex] = row;
            }

            saveMessages(remoteId, rows);
            upsertThread(remoteId, {
              lastMessageAt: new Date().toISOString(),
            });
          },
        }),
      }),
      [aui],
    );

    return (
      <RuntimeAdapterProvider adapters={{ history }}>
        {children}
      </RuntimeAdapterProvider>
    );
  },
};

"use client";

import type { ReactNode } from "react";
import {
  AssistantRuntimeProvider,
  useRemoteThreadListRuntime,
} from "@assistant-ui/react";
import { useChatRuntime } from "@assistant-ui/react-ai-sdk";
import { threadListAdapter } from "@/lib/persistence/thread-adapter";

export function MyRuntimeProvider({ children }: { children: ReactNode }) {
  const runtime = useRemoteThreadListRuntime({
    runtimeHook: () => useChatRuntime(),
    adapter: threadListAdapter,
  });

  return (
    <AssistantRuntimeProvider runtime={runtime}>
      {children}
    </AssistantRuntimeProvider>
  );
}

"use client";

import { Thread } from "@/components/assistant-ui/thread";
import { ThreadList } from "@/components/assistant-ui/thread-list";
import {
  AuiConfig,
  AuiProvider,
  Suggestions,
  useAui,
} from "@assistant-ui/react";

function ThreadWithSuggestions() {
  const aui = useAui();
  const config = AuiConfig({
    suggestions: Suggestions([
      {
        title: "What's the weather",
        label: "in Tokyo right now?",
        prompt: "What's the weather in Tokyo?",
      },
      {
        title: "Tell me a fun fact",
        label: "about any topic",
        prompt: "Tell me a fun fact about space.",
      },
    ]),
  });

  return (
    <AuiProvider extends={aui} config={config}>
      <Thread />
    </AuiProvider>
  );
}

export default function Home() {
  return (
    <main className="grid h-full min-h-0 grid-cols-[280px_1fr]">
      <aside className="border-border flex min-h-0 flex-col border-r p-3">
        <h1 className="mb-3 px-2 text-sm font-semibold">AI Chat</h1>
        <ThreadList />
      </aside>
      <section className="min-h-0">
        <ThreadWithSuggestions />
      </section>
    </main>
  );
}

import type { Metadata } from "next";
import { TooltipProvider } from "@/components/ui/tooltip";
import { MyRuntimeProvider } from "./MyRuntimeProvider";
import "./globals.css";

export const metadata: Metadata = {
  title: "AI Chat",
  description: "assistant-ui chat app with AI SDK and local persistence",
};

export default function RootLayout({
  children,
}: Readonly<{
  children: React.ReactNode;
}>) {
  return (
    <html lang="en">
      <body className="h-dvh antialiased">
        <TooltipProvider>
          <MyRuntimeProvider>{children}</MyRuntimeProvider>
        </TooltipProvider>
      </body>
    </html>
  );
}

