  deleteMessages,
  loadMessages,
  loadThreads,
  saveMessages,
  saveThreads,
  type StoredMessage,
  type StoredThread,
} from "./storage";

const sortThreads = (threads: StoredThread[]) =>
  [...threads].sort((a, b) => {
    const aTime = new Date(a.lastMessageAt ?? a.createdAt).getTime();
    const bTime = new Date(b.lastMessageAt ?? b.createdAt).getTime();
    return bTime - aTime;
  });

const upsertThread = (
  remoteId: string,
  patch: Partial<Omit<StoredThread, "remoteId" | "createdAt">>,
) => {
  const threads = loadThreads();
  const index = threads.findIndex((thread) => thread.remoteId === remoteId);
  if (index === -1) {
    const createdAt = new Date().toISOString();
    threads.push({
      remoteId,
      status: "regular",
      createdAt,
      ...patch,
    });
  } else {
    threads[index] = { ...threads[index], ...patch };
  }
  saveThreads(sortThreads(threads));
};

const toRemoteThread = (thread: StoredThread) => ({
  remoteId: thread.remoteId,
  status: thread.status,
  title: thread.title,
  lastMessageAt: thread.lastMessageAt
    ? new Date(thread.lastMessageAt)
    : undefined,
});

